CREATE OR REPLACE FUNCTION public.network_create_distribution(_request uuid DEFAULT NULL,_trip uuid DEFAULT NULL,_amount integer DEFAULT NULL,_expires timestamptz DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.ride_requests; t public.trips; ws uuid; uid uuid; lat float8; lng float8; did uuid; source_id text; service text; area1 text; area2 text; d date; tm time; typ text; miles numeric; src text; represented uuid; BEGIN IF auth.uid() IS NULL OR _amount IS NULL OR _amount<=0 OR _expires IS NULL OR _expires<=now() THEN RAISE EXCEPTION 'Complete compensation and expiration'; END IF; IF (_request IS NULL)=(_trip IS NULL) THEN RAISE EXCEPTION 'Choose one source'; END IF; IF _request IS NOT NULL THEN SELECT * INTO r FROM public.ride_requests WHERE id=_request FOR UPDATE; IF NOT FOUND OR r.is_test OR r.trip_kind='medical_delivery' OR r.transport_type='delivery' THEN RAISE EXCEPTION 'Request is not available for passenger distribution'; END IF; IF NOT(public.admin_can('requests','manage') AND public.admin_can_account(r.workspace_id)) THEN RAISE EXCEPTION 'Distribution permission required'; END IF; IF r.status IN ('canceled','completed','declined','unavailable') OR r.assigned_provider_id IS NOT NULL THEN RAISE EXCEPTION 'Request is not available'; END IF; ws:=r.workspace_id; uid:=r.requester_user_id; represented:=r.on_behalf_of_user_id; source_id:=r.mfn_id; service:=r.transport_type; area1:=r.pickup_city; area2:=r.dropoff_city; d:=r.pickup_date; tm:=r.pickup_time; typ:=r.trip_type; miles:=r.distance_miles; lat:=r.pickup_lat; lng:=r.pickup_lng; src:=coalesce(r.intake_source,r.submitted_via,'public_form'); _trip:=r.promoted_trip_id; ELSE SELECT * INTO t FROM public.trips WHERE id=_trip FOR UPDATE; IF NOT FOUND OR t.trip_kind='medical_delivery' OR t.status IN ('canceled','completed') OR t.network_provider_workspace_id IS NOT NULL THEN RAISE EXCEPTION 'Trip is not available'; END IF; IF t.ride_request_id IS NOT NULL THEN SELECT * INTO r FROM public.ride_requests WHERE id=t.ride_request_id; ws:=r.workspace_id; ELSE SELECT CASE WHEN count(*)=1 THEN min(m.workspace_id::text)::uuid END INTO ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=t.created_by AND w.status='active'; END IF; IF ws IS NULL OR NOT public.network_workspace_access(ws,true) OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=ws AND account_type='provider') THEN RAISE EXCEPTION 'Trip sharing permission required'; END IF; IF t.assigned_to IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=ws AND user_id=t.assigned_to) THEN RAISE EXCEPTION 'Only the source business may share this trip'; END IF; uid:=coalesce(r.requester_user_id,t.created_by); represented:=r.on_behalf_of_user_id; source_id:=coalesce(r.mfn_id,t.display_id,t.trip_number); service:=t.transport_type; area1:=t.pickup_city; area2:=t.dropoff_city; d:=t.pickup_date; tm:=t.pickup_time; typ:=coalesce(r.trip_type,CASE WHEN t.round_trip THEN 'round_trip' ELSE 'one_way' END); miles:=coalesce(t.distance_miles,t.estimated_miles); lat:=t.pickup_lat; lng:=t.pickup_lng; src:='provider_shared'; END IF; IF lat IS NULL OR lng IS NULL OR lat NOT BETWEEN -90 AND 90 OR lng NOT BETWEEN -180 AND 180 OR nullif(trim(area1),'') IS NULL OR nullif(trim(area2),'') IS NULL OR d IS NULL OR tm IS NULL OR source_id IS NULL OR service NOT IN ('ambulatory','wheelchair','gurney','stretcher') THEN RAISE EXCEPTION 'Missing reliable pickup coordinates, general route, date/time, source ID or service'; END IF; INSERT INTO public.trip_distributions(request_id,trip_id,source_workspace_id,original_person_id,original_person_mfn_id,original_workspace_mfn_id,acting_person_id,acting_person_mfn_id,represented_person_id,submission_source,source_mfn_id,service_type,pickup_area,destination_area,pickup_date,pickup_time,trip_type,estimated_miles,amount_cents,capability,pickup_lat,pickup_lng,expires_at) VALUES(_request,_trip,ws,uid,(SELECT mfn_id FROM public.user_profiles WHERE user_id=uid),(SELECT mfn_id FROM public.workspaces WHERE id=ws),auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),represented,src,source_id,service,area1,area2,d,tm,typ,miles,_amount,CASE WHEN service='gurney' THEN 'stretcher' ELSE service END,lat,lng,_expires) RETURNING id INTO did; PERFORM public.network_audit(did,NULL,'ready_for_distribution',jsonb_build_object('source_mfn_id',source_id)); RETURN did; END $$;
CREATE OR REPLACE FUNCTION public.network_send_wave(_distribution uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_distributions; radius integer; wave uuid; p record; n integer:=0; oid uuid; BEGIN SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution FOR UPDATE; IF NOT FOUND OR NOT(public.admin_can('requests','manage') AND public.admin_can_account(d.source_workspace_id)) THEN RAISE EXCEPTION 'Operations distribution permission required'; END IF; IF d.selected_workspace_id IS NOT NULL OR d.expires_at<=now() OR d.status IN ('closed','canceled','unavailable') THEN RAISE EXCEPTION 'Distribution is no longer available'; END IF; radius:=CASE coalesce(d.current_radius,0) WHEN 0 THEN 20 WHEN 20 THEN 50 WHEN 50 THEN 100 WHEN 100 THEN 200 ELSE NULL END; IF radius IS NULL THEN RAISE EXCEPTION 'All distance stages have been sent'; END IF; INSERT INTO public.trip_distribution_waves(distribution_id,radius_miles,sent_by) VALUES(d.id,radius,auth.uid()) RETURNING id INTO wave; FOR p IN SELECT w.id FROM public.workspaces w JOIN public.provider_network_profiles np ON np.workspace_id=w.id WHERE w.account_type='provider' AND w.status='active' AND w.provider_verified AND NOT w.is_test_account AND np.visible AND np.accepting_connections AND np.service_base_verified_at IS NOT NULL AND np.service_base_lat BETWEEN -90 AND 90 AND np.service_base_lng BETWEEN -180 AND 180 AND (np.eligibility_expires_at IS NULL OR np.eligibility_expires_at>now()) AND d.capability=ANY(np.approved_service_types) AND w.id IS DISTINCT FROM d.source_workspace_id AND public.haversine_miles(d.pickup_lat,d.pickup_lng,np.service_base_lat,np.service_base_lng)<=radius AND EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles up ON up.user_id=m.user_id WHERE m.workspace_id=w.id AND up.status='active' AND NOT m.is_contractor AND (m.role IN ('owner','admin') OR m.can_manage_trips)) AND NOT EXISTS(SELECT 1 FROM public.provider_trip_offers o WHERE o.distribution_id=d.id AND o.provider_workspace_id=w.id) AND (NOT EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=w.id) OR EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=w.id AND v.status='active' AND (d.capability=ANY(v.service_capabilities) OR (d.capability='ambulatory' AND v.vehicle_type IN ('sedan','suv','van')) OR (d.capability='wheelchair' AND v.vehicle_type='wheelchair_van' AND v.wheelchair_capacity>0) OR (d.capability='stretcher' AND v.vehicle_type IN ('stretcher_van','ambulance'))) AND (d.capability<>'wheelchair' OR v.wheelchair_capacity>0) AND NOT EXISTS(SELECT 1 FROM public.trips x WHERE x.vehicle_id=v.id AND x.pickup_date=d.pickup_date AND x.status NOT IN ('completed','canceled') AND (x.pickup_time=d.pickup_time OR (x.estimated_duration_seconds>0 AND d.pickup_time>=x.pickup_time AND d.pickup_time<x.pickup_time+make_interval(secs=>x.estimated_duration_seconds)))))) LOOP INSERT INTO public.provider_trip_offers(distribution_id,wave_id,provider_workspace_id,amount_cents,expires_at) VALUES(d.id,wave,p.id,d.amount_cents,d.expires_at) ON CONFLICT(distribution_id,provider_workspace_id) DO NOTHING RETURNING id INTO oid; IF oid IS NOT NULL THEN n:=n+1; PERFORM public.network_notify(p.id,'New offer received',oid,false); END IF; END LOOP; UPDATE public.trip_distributions SET current_radius=radius,status='offers_sent',updated_at=now() WHERE id=d.id; PERFORM public.network_audit(d.id,NULL,'wave_sent',jsonb_build_object('radius',radius,'recipients',n)); RETURN jsonb_build_object('radius',radius,'recipients',n); END $$;
CREATE OR REPLACE FUNCTION public.network_accept_offer(_offer uuid,_approve boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.provider_trip_offers; d public.trip_distributions; tid uuid; comp record; BEGIN SELECT distribution_id INTO tid FROM public.provider_trip_offers WHERE id=_offer; SELECT * INTO d FROM public.trip_distributions WHERE id=tid FOR UPDATE; SELECT * INTO o FROM public.provider_trip_offers WHERE id=_offer FOR UPDATE; IF o.id IS NULL OR d.selected_workspace_id IS NOT NULL OR d.expires_at<=now() OR o.expires_at<=now() OR o.status NOT IN ('pending','revised','countered') THEN RETURN jsonb_build_object('ok',false,'error','This offer is no longer available'); END IF; IF _approve THEN IF NOT public.network_source_access(d.id,true) OR o.status<>'countered' THEN RAISE EXCEPTION 'Counteroffer approval permission required'; END IF; ELSE IF NOT public.network_workspace_access(o.provider_workspace_id,true) OR o.status='countered' THEN RAISE EXCEPTION 'Offer acceptance permission required'; END IF; END IF; IF NOT EXISTS(SELECT 1 FROM public.workspaces w JOIN public.provider_network_profiles np ON np.workspace_id=w.id WHERE w.id=o.provider_workspace_id AND w.status='active' AND w.provider_verified AND NOT w.is_test_account AND np.visible AND np.service_base_verified_at IS NOT NULL AND d.capability=ANY(np.approved_service_types) AND (np.eligibility_expires_at IS NULL OR np.eligibility_expires_at>now())) THEN RETURN jsonb_build_object('ok',false,'error','This offer is no longer available'); END IF; tid:=d.trip_id; IF tid IS NULL THEN SELECT promoted_trip_id INTO tid FROM public.ride_requests WHERE id=d.request_id FOR UPDATE; IF tid IS NULL THEN IF EXISTS(SELECT 1 FROM public.ride_requests WHERE id=d.request_id AND (is_test OR trip_kind='medical_delivery' OR transport_type='delivery')) THEN RAISE EXCEPTION 'Passenger request required'; END IF; tid:=public.promote_ride_request_to_trip(d.request_id); END IF; END IF; IF tid IS NULL THEN RAISE EXCEPTION 'Source trip unavailable'; END IF; PERFORM set_config('app.network_write','true',true); UPDATE public.trips SET network_provider_workspace_id=o.provider_workspace_id,network_distribution_id=d.id,network_status='reserved',reservation_state='unconfirmed' WHERE id=tid AND network_provider_workspace_id IS NULL; IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','This offer is no longer available'); END IF; UPDATE public.trip_distributions SET selected_workspace_id=o.provider_workspace_id,selected_offer_id=o.id,accepted_by=CASE WHEN _approve THEN (SELECT actor_id FROM public.trip_offer_negotiations WHERE offer_id=o.id AND side='provider' ORDER BY created_at DESC LIMIT 1) ELSE auth.uid() END,approved_by=auth.uid(),status='provider_selected',trip_id=tid,updated_at=now() WHERE id=d.id; UPDATE public.provider_trip_offers SET status='accepted',accepted_by=auth.uid(),approved_by=auth.uid(),updated_at=now() WHERE id=o.id; FOR comp IN SELECT id,provider_workspace_id FROM public.provider_trip_offers WHERE distribution_id=d.id AND id<>o.id AND status IN ('pending','countered','revised') LOOP UPDATE public.provider_trip_offers SET status='closed',updated_at=now() WHERE id=comp.id; PERFORM public.network_notify(comp.provider_workspace_id,'Offer no longer available',comp.id,false); END LOOP; IF _approve THEN INSERT INTO public.trip_offer_negotiations(offer_id,actor_id,actor_mfn_id,side,action,amount_cents) VALUES(o.id,auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),'source','accept',o.amount_cents); END IF; PERFORM public.network_audit(d.id,o.id,'provider_selected',jsonb_build_object('provider_workspace_id',o.provider_workspace_id,'trip_id',tid,'amount_cents',o.amount_cents)); PERFORM public.network_notify(o.provider_workspace_id,'Provider selected',o.id,false); IF d.source_workspace_id IS NOT NULL THEN PERFORM public.network_notify(d.source_workspace_id,'Provider selected',o.id,false); END IF; RETURN jsonb_build_object('ok',true,'trip_id',tid); END $$;
CREATE OR REPLACE FUNCTION public.network_respond_offer(_offer uuid,_action text,_amount integer DEFAULT NULL,_note text DEFAULT NULL,_expires timestamptz DEFAULT NULL,_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.provider_trip_offers; d public.trip_distributions; did uuid; side text; BEGIN SELECT distribution_id INTO did FROM public.provider_trip_offers WHERE id=_offer; SELECT * INTO d FROM public.trip_distributions WHERE id=did FOR UPDATE; SELECT * INTO o FROM public.provider_trip_offers WHERE id=_offer FOR UPDATE; IF o.id IS NULL OR d.selected_workspace_id IS NOT NULL OR d.expires_at<=now() OR o.expires_at<=now() OR o.status NOT IN ('pending','countered','revised') THEN RETURN jsonb_build_object('ok',false,'error','This offer is no longer available'); END IF; IF _action IN ('counter','decline') AND public.network_workspace_access(o.provider_workspace_id,true) THEN side:='provider'; ELSIF _action IN ('revise','reject_counter') AND public.network_source_access(d.id,true) THEN side:='source'; ELSE RAISE EXCEPTION 'Offer response permission required'; END IF; IF length(coalesce(_note,''))>300 OR _reason IS NOT NULL AND _reason NOT IN ('no_driver','no_vehicle','schedule','distance','rate','other') THEN RAISE EXCEPTION 'Invalid business response'; END IF; IF _action IN ('counter','revise') THEN IF _amount IS NULL OR _amount<=0 OR _expires IS NULL OR _expires<=now() OR _expires>d.expires_at THEN RAISE EXCEPTION 'Complete amount and expiration within the distribution expiration'; END IF; IF _action='counter' AND o.status='countered' THEN RAISE EXCEPTION 'Only one active counteroffer is allowed'; END IF; IF _action='revise' AND o.status<>'countered' THEN RAISE EXCEPTION 'No active counteroffer'; END IF; INSERT INTO public.trip_offer_negotiations(offer_id,actor_id,actor_mfn_id,side,action,amount_cents,business_note,expires_at) VALUES(o.id,auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),side,_action,_amount,nullif(trim(_note),''),_expires); UPDATE public.provider_trip_offers SET status=CASE WHEN _action='counter' THEN 'countered' ELSE 'revised' END,amount_cents=_amount,expires_at=_expires,updated_at=now() WHERE id=o.id; UPDATE public.trip_distributions SET status='negotiating',updated_at=now() WHERE id=d.id; ELSE IF _action='reject_counter' AND o.status<>'countered' THEN RAISE EXCEPTION 'No active counteroffer'; END IF; INSERT INTO public.trip_offer_negotiations(offer_id,actor_id,actor_mfn_id,side,action,business_note) VALUES(o.id,auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),side,'decline',nullif(trim(_note),'')); UPDATE public.provider_trip_offers SET status='declined',decline_reason=_reason,updated_at=now() WHERE id=o.id; END IF; PERFORM public.network_audit(d.id,o.id,_action,jsonb_build_object('amount_cents',_amount,'reason',_reason)); IF side='source' THEN PERFORM public.network_notify(o.provider_workspace_id,CASE WHEN _action='revise' THEN 'Revised offer received' ELSE 'Counteroffer declined' END,o.id,false); ELSIF d.source_workspace_id IS NOT NULL THEN PERFORM public.network_notify(d.source_workspace_id,CASE WHEN _action='counter' THEN 'Counteroffer received' ELSE 'Offer declined' END,o.id,false); END IF; RETURN jsonb_build_object('ok',true); END $$;
CREATE OR REPLACE FUNCTION public.network_list_offers() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'mfn_id',o.mfn_id,'distribution_id',d.id,'source_mfn_id',d.source_mfn_id,'service_type',d.service_type,'pickup_area',d.pickup_area,'destination_area',d.destination_area,'pickup_date',d.pickup_date,'pickup_time',d.pickup_time,'trip_type',d.trip_type,'estimated_miles',d.estimated_miles,'amount_cents',o.amount_cents,'capability',d.capability,'expires_at',o.expires_at,'status',CASE WHEN o.status IN ('pending','countered','revised') AND o.expires_at<=now() THEN 'expired' ELSE o.status END,'provider_workspace_id',o.provider_workspace_id) ORDER BY o.created_at DESC),'[]'::jsonb) FROM public.provider_trip_offers o JOIN public.trip_distributions d ON d.id=o.distribution_id WHERE public.network_workspace_access(o.provider_workspace_id,true) $$;
CREATE OR REPLACE FUNCTION public.network_list_activity() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d record; BEGIN FOR d IN SELECT * FROM public.trip_distributions WHERE public.network_source_access(id,false) AND selected_workspace_id IS NULL AND status NOT IN ('needs_attention','closed','canceled','unavailable') AND created_at<=now()-interval '24 hours' LOOP UPDATE public.trip_distributions SET status='needs_attention',updated_at=now() WHERE id=d.id; PERFORM public.network_audit(d.id,NULL,'needs_attention','{}'); IF d.source_workspace_id IS NOT NULL THEN PERFORM public.network_notify(d.source_workspace_id,'Distribution needs attention',NULL,true); END IF; END LOOP; RETURN (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]'::jsonb) FROM (SELECT d.*, (SELECT display_name FROM public.workspaces WHERE id=d.source_workspace_id) source_business, public.network_source_access(d.id,true) can_manage, (SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.created_at),'[]'::jsonb) FROM public.provider_trip_offers o WHERE o.distribution_id=d.id) offers,(SELECT coalesce(jsonb_agg(to_jsonb(w) ORDER BY w.sent_at),'[]'::jsonb) FROM public.trip_distribution_waves w WHERE w.distribution_id=d.id) waves,(SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.created_at),'[]'::jsonb) FROM public.trip_offer_negotiations n JOIN public.provider_trip_offers o ON o.id=n.offer_id WHERE o.distribution_id=d.id) negotiations,(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.created_at),'[]'::jsonb) FROM public.trip_network_events e WHERE e.distribution_id=d.id) events FROM public.trip_distributions d WHERE public.network_source_access(d.id,false)) x); END $$;
CREATE OR REPLACE FUNCTION public.guard_network_trip_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.network_provider_workspace_id IS DISTINCT FROM OLD.network_provider_workspace_id OR NEW.network_distribution_id IS DISTINCT FROM OLD.network_distribution_id OR NEW.network_status IS DISTINCT FROM OLD.network_status) AND coalesce(current_setting('app.network_write',true),'')<>'true' THEN RAISE EXCEPTION 'Controlled network assignment required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_network_trip_fields BEFORE UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION public.guard_network_trip_fields();
CREATE OR REPLACE FUNCTION public.trg_promote_ride_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN NEW; END $$;
COMMENT ON FUNCTION public.trg_promote_ride_request() IS 'New requests stay received/under review. Passenger promotion occurs only after authorized controlled acceptance; existing trips remain unchanged.';
REVOKE ALL ON FUNCTION public.network_create_distribution(uuid,uuid,integer,timestamptz),public.network_send_wave(uuid),public.network_accept_offer(uuid,boolean),public.network_respond_offer(uuid,text,integer,text,timestamptz,text),public.network_list_offers(),public.network_list_activity() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_create_distribution(uuid,uuid,integer,timestamptz),public.network_send_wave(uuid),public.network_accept_offer(uuid,boolean),public.network_respond_offer(uuid,text,integer,text,timestamptz,text),public.network_list_offers(),public.network_list_activity() TO authenticated;
REVOKE EXECUTE ON FUNCTION public.promote_ride_request_to_trip(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.guard_network_profile_insert_eligibility() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.is_master_admin(auth.uid()) THEN NEW.approved_service_types:='{}'; NEW.service_base_verified_at:=NULL; NEW.service_base_lat:=NULL; NEW.service_base_lng:=NULL; NEW.eligibility_expires_at:=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_network_profile_insert_eligibility BEFORE INSERT ON public.provider_network_profiles FOR EACH ROW EXECUTE FUNCTION public.guard_network_profile_insert_eligibility();